import{_ as n,D as r,c as a,j as t,a as e,I as o,a4 as i,o as d}from"./chunks/framework.P4k6vdAm.js";const h="/assets/permission-gating-config.fJraOSY1.png",C=JSON.parse('{"title":"Permission Gating","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-authentication/openid-connect-bearer-token/permission-gating.md","filePath":"docs/endpoint-authentication/openid-connect-bearer-token/permission-gating.md","lastUpdated":1793090203000}'),l={name:"docs/endpoint-authentication/openid-connect-bearer-token/permission-gating.md"},c={id:"permission-gating",tabindex:"-1"},p=t("a",{class:"header-anchor",href:"#permission-gating","aria-label":'Permalink to "Permission Gating <Badge type="tip" text="1.124.0" />"'},"​",-1),u=i('<p>Permission gating is an optional extension of <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html">Open ID Connect Bearer Token</a> authentication. As well as checking that the caller&#39;s token is valid, AireGlu checks that the <strong>user behind the token holds specific permissions</strong> before the endpoint runs.</p><p>Use it when:</p><ul><li>Only some users of an application should be able to call an endpoint (for example, only users who can <code>edit:widget</code> should be able to update a widget)</li><li>The endpoint is exposed as an <a href="/docs/mcp-servers/permissions.html">MCP tool or resource</a> and should only be visible to users who are allowed to use it</li><li>Permissions are already managed centrally in AireIdentity and you don&#39;t want to repeat them in endpoint logic</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Permission gating runs as part of authentication, after the token has been validated:</p><ol><li>The caller sends a user access token (Bearer header or form POST, see <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html#how-callers-pass-a-token">How callers pass a token</a>).</li><li>AireGlu validates the token&#39;s signature, issuer, expiry, audience and scopes as normal.</li><li>AireGlu asks the <strong>permission source</strong> which permissions the user holds in each configured <strong>Target Scope</strong>, using the <strong>caller&#39;s own token</strong>.</li><li>The caller must hold <strong>every</strong> listed permission in <strong>every</strong> gated Target Scope. If anything is missing, the request is refused.</li><li>On success the endpoint runs, and the caller&#39;s token is available via liquid within the AireGlu Tasks <code>request.userToken</code>.</li></ol><h3 id="why-it-works-this-way" tabindex="-1">Why it works this way <a class="header-anchor" href="#why-it-works-this-way" aria-label="Permalink to &quot;Why it works this way&quot;">​</a></h3><ul><li><strong>The user&#39;s own token is used for the lookup.</strong> AireIdentity only returns permissions for the user the token belongs to. A caller cannot ask about anyone else&#39;s permissions, and AireGlu doesn&#39;t need a privileged service account to read them.</li><li><strong>The check is live on every request.</strong> Lookups are not cached, so revoking a role or policy in AireIdentity takes effect on the next call. There is no window where a removed user can keep calling the endpoint.</li><li><strong>It fails closed.</strong> If the permission source is unreachable, returns an error or returns nothing, the request is rejected. An outage never silently grants access.</li><li><strong>It lives on the endpoint, not on whatever calls it.</strong> The same gate applies whether the endpoint is called over HTTP, from an iframe or as an MCP tool. You configure it once.</li></ul><h2 id="configuring-permission-gating" tabindex="-1">Configuring permission gating <a class="header-anchor" href="#configuring-permission-gating" aria-label="Permalink to &quot;Configuring permission gating&quot;">​</a></h2><p>In the endpoint editor, open <strong>Authentication</strong> and add (or edit) an <strong>Open ID Connect Bearer Token</strong> method. Configure <strong>Authority</strong>, <strong>Audiences</strong> and optional <strong>Scopes</strong> as described in <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html#configuring-an-endpoint">Configuring an endpoint</a>, then:</p><ol><li>Under <strong>Permission gating</strong>, tick <strong>Fetch and validate permissions for Target Scope(s)</strong>.</li><li>Choose a <strong>Permission source</strong>: <ul><li><strong>AireIdentity (default)</strong>: permissions are read live from AireIdentity&#39;s policy service.</li><li><strong>Custom Endpoint</strong>: see <a href="#custom-permission-source">Custom permission source</a>.</li></ul></li><li>For each <strong>Target Scope</strong>: <ul><li>Enter the <strong>Target Scope</strong>, the scope of the target application in the permission source (for example <code>PatientRecordsApi</code>).</li><li>Add the <strong>Permissions</strong> the caller must hold in that scope. For AireIdentity these are in <code>action:resource</code> format (for example <code>read:patient</code>). Type each permission and press <strong>Enter</strong>.</li></ul></li><li>Click <strong>Add Target Scope</strong> to gate on further scopes.</li><li>Save the endpoint.</li></ol><p><img src="'+h+'" alt="Permission gating configured on an Open ID Connect Bearer Token method" width="473"></p><table><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Fetch and validate permissions for Target Scope(s)</strong></td><td>No</td><td>Turns permission gating on. Unticking it removes all Target Scopes.</td></tr><tr><td><strong>Permission source</strong></td><td>Yes, when gating is on</td><td><strong>AireIdentity (default)</strong> or <strong>Custom Endpoint</strong>.</td></tr><tr><td><strong>Target Scope</strong></td><td>Yes, per row</td><td>The scope in the permission source to check. Supports <a href="/docs/getting-started/variables.html">variables</a> and <a href="/docs/getting-started/secrets.html">secrets</a>. Must not contain spaces or commas, and must be unique on the endpoint.</td></tr><tr><td><strong>Permissions</strong></td><td>No</td><td>The permissions required in that scope. With <strong>AireIdentity</strong>, each must be in <code>action:resource</code> format. With <strong>Custom Endpoint</strong>, each can be any single value with no spaces or commas. Permissions are literal values; variables are not resolved.</td></tr></tbody></table><h3 id="target-scope-vs-scopes" tabindex="-1">Target Scope vs Scopes <a class="header-anchor" href="#target-scope-vs-scopes" aria-label="Permalink to &quot;Target Scope vs Scopes&quot;">​</a></h3><p>The <strong>Scopes</strong> field and <strong>Target Scope</strong> look similar but answer different questions:</p><table><thead><tr><th></th><th><strong>Scopes</strong></th><th><strong>Target Scope</strong></th></tr></thead><tbody><tr><td>Checks</td><td>The <code>scope</code> claim inside the token</td><td>The user&#39;s permissions in the permission source (AireIdentity&#39;s policy service, or a custom endpoint)</td></tr><tr><td>Answers</td><td>&quot;Was this token issued for this kind of call?&quot;</td><td>&quot;Is this user allowed to do this?&quot;</td></tr><tr><td>Example</td><td><code>AireGluRuntimeApi</code></td><td><code>PatientRecordsApi</code></td></tr></tbody></table><p>The Target Scope is usually the scope of the <strong>application the endpoint acts for</strong>, which is often not a scope the caller&#39;s token carries.</p><h3 id="matching-rules" tabindex="-1">Matching rules <a class="header-anchor" href="#matching-rules" aria-label="Permalink to &quot;Matching rules&quot;">​</a></h3><ul><li><strong>All</strong> Target Scopes must pass, and within each one the user must hold <strong>all</strong> listed permissions (AND, not OR). To allow &quot;either A or B&quot;, create separate endpoints or use a custom permission source.</li><li>Scope and permission names are compared case-insensitively.</li><li>A Target Scope with <strong>no permissions</strong> doesn&#39;t trigger a lookup. It still appears in <a href="#using-target-scopes-in-liquid"><code>authentication.targetScopes</code></a>, which is useful for passing a scope to a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection without gating on it.</li><li>Only one Open ID Connect Bearer Token method per endpoint version can have Target Scopes.</li><li>If the endpoint has other authentication methods, <strong>all</strong> of them must still pass.</li></ul><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>The <strong>Authority</strong> must be your AireIdentity instance when using the AireIdentity permission source. Lookups always go to the AireIdentity instance AireGlu itself is configured with, so tokens from third-party identity providers can&#39;t be gated this way. To gate them, use a <a href="#custom-permission-source">custom permission source</a>.</li><li>With the AireIdentity source, users get permissions through roles and policies in AireIdentity. A user with no role granting the permission is rejected.</li></ul>',21),g={id:"what-the-caller-sees",tabindex:"-1"},m=t("a",{class:"header-anchor",href:"#what-the-caller-sees","aria-label":'Permalink to "What the caller sees <Badge type="tip" text="1.125.0" />"'},"​",-1),k=i(`<p>The status code tells the caller why the request was refused, and whether trying again could help.</p><table><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Token valid, all permissions held</td><td>Endpoint runs</td></tr><tr><td>Token missing or invalid</td><td><strong>401 Unauthorized</strong>. The caller needs a new token.</td></tr><tr><td>Token valid, a permission missing</td><td><strong>403 Forbidden</strong>. The user isn&#39;t allowed to call this endpoint.</td></tr><tr><td>Permission check can&#39;t be done because of a setup problem, for example a wrong Target Scope or Authority</td><td><strong>500 Internal Server Error</strong>. Fix the configuration; retrying won&#39;t help.</td></tr><tr><td>Permission source returned a response AireGlu can&#39;t use</td><td><strong>502 Bad Gateway</strong></td></tr><tr><td>Permission source is temporarily unavailable, slow or busy</td><td><strong>503 Service Unavailable</strong>. The caller can retry later.</td></tr><tr><td>Called as an MCP tool or resource</td><td>See <a href="/docs/mcp-servers/permissions.html">MCP Permissions</a>: the tool is hidden from the user rather than returning an error</td></tr></tbody></table><p>Whatever the failure, the endpoint doesn&#39;t run (fail closed).</p><p>In the endpoint&#39;s <a href="/docs/getting-started/metrics.html">usage data</a>, a missing or invalid token is recorded as an <strong>Endpoint Authentication Failure</strong>, a missing permission as an <strong>Endpoint Authorization Failure</strong>, and a failed permission check (500, 502 or 503) as an <strong>Endpoint Permission Lookup Failure</strong>, with a short reason where one is available.</p><h2 id="using-target-scopes-in-liquid" tabindex="-1">Using target scopes in Liquid <a class="header-anchor" href="#using-target-scopes-in-liquid" aria-label="Permalink to &quot;Using target scopes in Liquid&quot;">​</a></h2><p>The configured Target Scope names are available in task templates as <code>authentication.targetScopes</code>:</p><div class="language-liquid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">liquid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes[0] }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ authentication.targetScopes | </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">join:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39; &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span></code></pre></div><p>This contains the <strong>configured</strong> scope names (after variables are resolved), not the permissions the user holds. Its main use is to keep the scope you gate on and the scope you request downstream in step. For example, use it as the <code>scope</code> parameter of a <a href="/docs/connections/delegate-exchange.html#liquid-mapping">Delegate Exchange</a> connection.</p><p><code>authentication.targetScopes</code> is empty in Preview.</p><h2 id="permission-gating-and-downstream-calls" tabindex="-1">Permission gating and downstream calls <a class="header-anchor" href="#permission-gating-and-downstream-calls" aria-label="Permalink to &quot;Permission gating and downstream calls&quot;">​</a></h2><p>Permission gating decides <strong>whether the endpoint runs</strong>. It doesn&#39;t change the credentials the endpoint&#39;s tasks use when they call other systems.</p><p>If a task calls a downstream API <strong>as the user</strong>, use a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection. It swaps <code>request.userToken</code> for a token scoped to the downstream API. The downstream API should still enforce its own data-level access (for example, which patient records this user may see). Permission gating is the first check, not the only one.</p><p>A typical layered setup:</p><table><thead><tr><th>Layer</th><th>Question</th><th>Enforced by</th></tr></thead><tbody><tr><td>Endpoint</td><td>Can this user call this endpoint at all?</td><td>Permission gating</td></tr><tr><td>Downstream credential</td><td>What may AireGlu do on this user&#39;s behalf?</td><td>Delegate Exchange connection, Target Scope on the exchanged token</td></tr><tr><td>Data</td><td>Which records can this user see?</td><td>The downstream API</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Gate on the action, not the user.</strong> Grant permissions through roles and policies in AireIdentity rather than per-user, so access is managed in one place.</li><li><strong>Keep permission sets small and specific.</strong> Required permissions are ANDed, so each one you add narrows who can call the endpoint.</li><li><strong>Use one Target Scope per application.</strong> Add a second Target Scope only when the endpoint genuinely acts on two applications (for example records and billing).</li><li><strong>Don&#39;t treat gating as data security.</strong> Keep record-level checks in the downstream system, and pass the user&#39;s identity to it with a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection.</li><li><strong>Expect a lookup per request.</strong> Each gated call makes a live request to the permission source. For high-volume, non-user traffic, use <a href="/docs/endpoint-authentication/client-credentials.html">Client Credentials</a> on a separate endpoint instead.</li><li><strong>Test with a user who lacks the permission.</strong> Confirm they get 403 (or don&#39;t see the MCP tool) before going live.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>These apply to both permission sources. For problems specific to a custom permission source, see <a href="#troubleshooting-a-custom-permission-source">Troubleshooting a custom permission source</a>.</p><table><thead><tr><th>Symptom</th><th>Things to check</th></tr></thead><tbody><tr><td>401</td><td>The token itself was rejected, before permissions were checked. See <a href="/docs/endpoint-authentication/openid-connect-bearer-token.html#troubleshooting">Open ID Connect Bearer Token troubleshooting</a>.</td></tr><tr><td>403 for a user who should have access</td><td>Check the user holds <strong>every</strong> listed permission in <strong>every</strong> Target Scope. With AireIdentity, check their role grants them. Check the Target Scope is the permission source&#39;s scope name, not the token&#39;s scope.</td></tr><tr><td>500 for everyone</td><td>A setup problem. Check the usage data reason. With AireIdentity, check the Target Scope is a valid scope in AireIdentity and <strong>Authority</strong> is your AireIdentity instance.</td></tr><tr><td>502 or 503</td><td>The permission source failed or is unavailable. Check the usage data reason. A 503 is usually temporary, so try again later.</td></tr><tr><td>Permission rejected on save</td><td>With AireIdentity, permissions must be <code>action:resource</code> format with no spaces or commas, for example <code>read:patient</code>.</td></tr><tr><td><code>authentication.targetScopes</code> is empty</td><td>It is always empty in Preview. Check the endpoint has an Open ID Connect Bearer Token method with at least one Target Scope.</td></tr></tbody></table><h2 id="custom-permission-source" tabindex="-1">Custom permission source <a class="header-anchor" href="#custom-permission-source" aria-label="Permalink to &quot;Custom permission source&quot;">​</a></h2><p>By default, AireGlu asks AireIdentity which permissions a user holds. If an application&#39;s permissions are held somewhere else, such as AireCentre, Microsoft Entra or Keycloak, you can build an AireGlu endpoint that answers the same question instead. This is the <strong>permission source endpoint</strong>.</p><p>AireGlu calls the permission source endpoint in place of AireIdentity. Everything else about permission gating stays the same: the caller must still hold every listed permission in every Target Scope, and any failure denies access.</p><h3 id="how-it-works-1" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works-1" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>The caller sends their access token to the gated endpoint, as normal.</li><li>AireGlu validates the token against the <strong>Authority</strong>, <strong>Audiences</strong> and <strong>Scopes</strong> as normal.</li><li>AireGlu sends a <code>POST</code> request to the permission source endpoint. The request contains the Target Scopes and permissions to check, and the caller&#39;s access token.</li><li>The permission source endpoint works out which of those permissions the user holds, typically by calling another system, and returns them.</li><li>AireGlu compares the response with the required permissions. If every required permission is present in every Target Scope, the gated endpoint runs.</li></ol><h3 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h3><ol><li><a href="#building-the-permission-source-endpoint">Build the permission source endpoint</a> and save it.</li><li>Open the endpoint you want to gate. Under <strong>Authentication</strong>, on its Open ID Connect Bearer Token method, tick <strong>Fetch and validate permissions for Target Scope(s)</strong>.</li><li>Under <strong>Permission source</strong>, select <strong>Custom Endpoint</strong>.</li><li>Choose the permission source <strong>Endpoint</strong> and its <strong>Version</strong>. The list shows every endpoint in the tenant apart from the one you&#39;re editing.</li><li>Add the Target Scopes and Permissions. With a custom source, a permission can be any single value with no spaces or commas, for example <code>Tasks.Read</code>, <code>admin</code> or <code>read:orders</code>. It doesn&#39;t need to be in <code>action:resource</code> format.</li><li>Save the endpoint.</li></ol><p>AireGlu checks the permission source when you save. You&#39;ll see an error if the endpoint doesn&#39;t exist, the version doesn&#39;t exist (including <strong>Default</strong> when the endpoint has no default version), or the endpoint points at itself.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With a custom source, the <strong>Authority</strong> doesn&#39;t have to be AireIdentity. AireGlu still validates the token against whichever Authority you set, then leaves the permission check to your endpoint. This lets you gate endpoints for users of third-party identity providers.</p></div><h3 id="building-the-permission-source-endpoint" tabindex="-1">Building the permission source endpoint <a class="header-anchor" href="#building-the-permission-source-endpoint" aria-label="Permalink to &quot;Building the permission source endpoint&quot;">​</a></h3><p>The permission source endpoint is an ordinary AireGlu endpoint. It must:</p><ul><li>Accept <code>POST</code> requests with a JSON body (see <a href="#request">Request</a>).</li><li>Return a <code>200</code> status and a JSON body (see <a href="#response">Response</a>).</li></ul><h4 id="request" tabindex="-1">Request <a class="header-anchor" href="#request" aria-label="Permalink to &quot;Request&quot;">​</a></h4><p>AireGlu sends this body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;targetScopePermissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OrdersApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read:orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit:orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;accessToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eyJhbGciOi...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>targetScopePermissions</code></td><td>One entry per Target Scope that has permissions on the gated endpoint. Target Scopes with no permissions are not sent.</td></tr><tr><td><code>targetScopePermissions[].scope</code></td><td>The Target Scope name, after variables are resolved.</td></tr><tr><td><code>targetScopePermissions[].permissions</code></td><td>The permissions the gated endpoint requires in that scope.</td></tr><tr><td><code>accessToken</code></td><td>The caller&#39;s access token, unchanged. Use it to look the user up, or exchange it with a <a href="/docs/connections/delegate-exchange.html">Delegate Exchange</a> connection to call another system as the user.</td></tr></tbody></table><p>Paste the example above into the endpoint&#39;s <a href="/docs/endpoint-input/input.html">input</a> dialog so the schema is generated and the fields are available in Liquid, for example <span><code>{{ data.accessToken }}</code></span> and <span><code>{{ data.targetScopePermissions }}</code></span>.</p><p>The <code>accessToken</code> is sent in the body, not as a header. AireGlu doesn&#39;t use it to authenticate the call; it&#39;s there so your tasks can use it.</p><h4 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h4><p>Return the permissions the user <strong>holds</strong>, grouped by scope:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scopePermissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OrdersApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;permissions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read:orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>scopePermissions</code></td><td>Required. One entry per scope. An empty list (<code>[]</code>) means the user holds nothing.</td></tr><tr><td><code>scopePermissions[].scope</code></td><td>The scope name. Must match a Target Scope from the request.</td></tr><tr><td><code>scopePermissions[].permissions</code></td><td>The permissions the user holds in that scope.</td></tr></tbody></table><p>How AireGlu reads the response:</p><ul><li>Scope and permission names are matched exactly, ignoring case.</li><li>A scope that is missing from the response counts as &quot;no permissions held&quot; in that scope.</li><li>Extra scopes or permissions the gated endpoint didn&#39;t ask for are ignored. You can return everything the user holds, or only the requested permissions they hold.</li><li>In the example above, the user holds <code>read:orders</code> but not <code>edit:orders</code>, so access is denied.</li></ul><p>You decide how the endpoint works out the user&#39;s permissions. For example, it could call AireCentre or another API with an <a href="/docs/endpoints/http-request.html">HTTP Request</a> task, then build the response with an <a href="/docs/endpoints/http-response.html">HTTP Response</a> task.</p>`,44),y={id:"failures-retries-and-timeouts",tabindex:"-1"},b=t("a",{class:"header-anchor",href:"#failures-retries-and-timeouts","aria-label":'Permalink to "Failures, retries and timeouts <Badge type="tip" text="1.125.0" />"'},"​",-1),f=i('<p>To deny a user, return <code>200</code> without the permission. Don&#39;t return an error status such as <code>403</code>: AireGlu treats any non-success status as the permission source endpoint failing, not as a decision about the user.</p><p>The lookup fails closed. Access is <strong>denied</strong>, and the caller gets the status shown, if the permission source endpoint:</p><table><thead><tr><th>Permission source endpoint</th><th>Caller gets</th></tr></thead><tbody><tr><td>Can&#39;t be reached, returns <code>408</code>, <code>429</code>, <code>502</code>, <code>503</code> or <code>504</code>, or doesn&#39;t respond in time</td><td><strong>503</strong></td></tr><tr><td>Returns any other non-success status, including <code>500</code>, <code>400</code> and <code>404</code></td><td><strong>502</strong></td></tr><tr><td>Returns a body that is empty, isn&#39;t JSON, or has no <code>scopePermissions</code> field</td><td><strong>502</strong></td></tr></tbody></table><p>If the endpoint can&#39;t be reached or returns <code>408</code>, <code>429</code>, <code>502</code>, <code>503</code> or <code>504</code>, AireGlu retries <strong>once</strong> after about half a second. Other errors, including <code>500</code>, are not retried. The whole lookup, including the retry, must finish within <strong>15 seconds</strong>.</p><p>When the permission source endpoint fails, it is logged in usage data and sends its own error email, the same as any other endpoint. The lookup carries the gated request&#39;s transaction and correlation IDs, so you can find both calls together in <a href="/docs/getting-started/metrics.html">usage data</a>.</p><p>There is no caching. The permission source endpoint is called on every request to the gated endpoint (and, for MCP, every time a gated tool is listed or called).</p><h3 id="best-practices-for-the-permission-source-endpoint" tabindex="-1">Best practices for the permission source endpoint <a class="header-anchor" href="#best-practices-for-the-permission-source-endpoint" aria-label="Permalink to &quot;Best practices for the permission source endpoint&quot;">​</a></h3><ul><li><strong>Use Internal Only authentication.</strong> Don&#39;t give it an Open ID Connect method or a permission source of its own. Nothing outside AireGlu should be able to call it.</li><li><strong>Keep Debug Mode off.</strong> The request contains the caller&#39;s access token. With <a href="/docs/getting-started/endpoints/debugging.html">Debug Mode</a> on, it would be stored with the debug data.</li><li><strong>Don&#39;t log or map the access token.</strong> Only pass <code>accessToken</code> to the task that needs it, such as a Delegate Exchange connection. Don&#39;t write it to an audit, email, response or any other output.</li><li><strong>Don&#39;t delete or re-version it while it&#39;s in use.</strong> Gated endpoints look it up by name and version. If it&#39;s removed, or the selected version (or <strong>Default</strong>) changes to something that doesn&#39;t return the expected response, every gated endpoint that uses it denies access.</li><li><strong>Keep it fast.</strong> It runs before every gated request, so slow lookups slow down every call.</li><li><strong>Make it read-only.</strong> It may be called twice for one request (because of the retry), so it shouldn&#39;t change anything.</li></ul><h3 id="troubleshooting-a-custom-permission-source" tabindex="-1">Troubleshooting a custom permission source <a class="header-anchor" href="#troubleshooting-a-custom-permission-source" aria-label="Permalink to &quot;Troubleshooting a custom permission source&quot;">​</a></h3><table><thead><tr><th>Gated endpoint returns</th><th>Things to check</th></tr></thead><tbody><tr><td>403 for a user who should have access</td><td>Check the permission source endpoint&#39;s response. Each <code>scope</code> must match a Target Scope, and <code>permissions</code> must include every required permission (case doesn&#39;t matter).</td></tr><tr><td>502 for everyone</td><td>Check the permission source endpoint&#39;s usage data for errors. Check it accepts <code>POST</code> and returns <code>200</code> with a <code>scopePermissions</code> field.</td></tr><tr><td>503</td><td>The permission source endpoint, or a system it calls, is unavailable or took longer than 15 seconds.</td></tr><tr><td>Permission rejected on save</td><td>Each permission must be a single value with no spaces or commas.</td></tr><tr><td>Permission source endpoint rejected on save</td><td>Check the endpoint exists, isn&#39;t the endpoint you&#39;re editing, and has the selected version. If you chose <strong>Default</strong>, check the endpoint has a default version set.</td></tr></tbody></table>',10);function w(T,E,v,q,A,P){const s=r("Badge");return d(),a("div",null,[t("h1",c,[e("Permission Gating "),o(s,{type:"tip",text:"1.124.0"}),e(),p]),u,t("h2",g,[e("What the caller sees "),o(s,{type:"tip",text:"1.125.0"}),e(),m]),k,t("h3",y,[e("Failures, retries and timeouts "),o(s,{type:"tip",text:"1.125.0"}),e(),b]),f])}const x=n(l,[["render",w]]);export{C as __pageData,x as default};
